                    dp_forward[v] = dp_forward[u] + w
                    updated = True
        if not updated:
            break

    # Step 2: Reverse graph
    # Build reverse adjacency list (v -> u)
    adj_rev = defaultdict(list)
    for u, v, w in edges:
        adj_rev[v].append((u, w))

    # Step 3: Reverse dynamic programming from t to all nodes
    # dp_reverse[u] = shortest distance from u to t (in original graph)
