    dp_reverse[t] = 0

    for _ in range(n):
        updated = False
        for u in range(n):
            if dp_reverse[u] == float('inf'):
                continue
            for v, w in adj_rev[u]:
                if dp_reverse[v] > dp_reverse[u] + w:
                    dp_reverse[v] = dp_reverse[u] + w
                    updated = True
        if not updated:
            break

    # Step 4: Combine forward and reverse info
    # For each node u, the shortest path from s to t can't be shorter than
    # dp_forward[u] + dp_reverse[u], assuming u is on the shortest path
