    expected = n * (n + 1) * (2 * n + 1) // 6
    return int((sum_sq - expected) ** 0.5)

def solve(nums):
    n = len(nums) - 1  # Since nums has n+1 elements
    xor_list = 0
    for num in nums:
        xor_list ^= num

    # Compute XOR from 1 to n
    mod = n % 4
    if mod == 0:
        xor_n = n
    elif mod == 1:
        xor_n = 1
    elif mod == 2:
        xor_n = n + 1
    else:  # mod == 3
        xor_n = 0

    return xor_list ^ xor_n

